import { createMCPServer } from 'mcp-use/server';
import { Resend } from 'resend';

// Get reply to email addresses from environment variable
const replierEmailAddresses = process.env.REPLY_TO_EMAIL_ADDRESSES?.split(',') || [];
const senderEmailAddress = process.env.FROM_EMAIL_ADDRESS;
const port = process.env.PORT || '3000';

// Create server instance
const server = createMCPServer('email-sending-service', {
  version: '1.0.0',
});

// Middleware to extract and validate API key from Authorization header
server.use((req: any, res: any, next: any) => {
  const authHeader = req.headers['authorization'];
  if (!authHeader) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }

  const token = [REDACTED], '');
  if (!token) {
    return res.status(401).json({
      error: 'Invalid Authorization header format. Use "Authorization: Bearer YOUR_API_KEY"',
    });
  }

  req.apiKey = token;
  next();
});

server.tool({
  name: 'send-email',
  description: 'Send an email using Resend',
  inputs: [
    { name: 'to', type: 'string', required: true, description: 'Recipient email address' },
    { name: 'subject', type: 'string', required: true, description: 'Email subject line' },
    { name: 'text', type: 'string', required: true, description: 'Plain text email content' },
    { name: 'html', type: 'string', required: false, description: 'HTML email content' },
    { name: 'cc', type: 'array', required: false, description: 'Optional array of CC email addresses' },
    { name: 'bcc', type: 'array', required: false, description: 'Optional array of BCC email addresses' },
    { name: 'scheduledAt', type: 'string', required: false, description: 'Optional parameter to schedule the email' },
    ...(senderEmailAddress ? [] : [{ name: 'from', type: 'string', required: true, description: 'Sender email address' } as const]),
    ...(replierEmailAddresses.length === 0 ? [{ name: 'replyTo', type: 'array', required: false, description: 'Optional email addresses for reply' } as const] : []),
  ],
  cb: async (params: any, context?: { req: any; res: any }) => {
    const { from, to, subject, text, html, replyTo, scheduledAt, cc, bcc } = params;
    const resend = new Resend(context?.req.apiKey);

    const fromEmailAddress = from ?? senderEmailAddress;
    const replyToEmailAddresses = replyTo ?? replierEmailAddresses;

    // Type check on from, since "from" is optionally included in the arguments schema
    // This should never happen.
    if (typeof fromEmailAddress !== 'string') {
      throw new Error('from argument must be provided.');
    }

    // Similar type check for "reply-to" email addresses.
    if (
      typeof replyToEmailAddresses !== 'string' &&
      !Array.isArray(replyToEmailAddresses)
    ) {
      throw new Error('replyTo argument must be provided.');
    }

    console.error(`Debug - Sending email with from: ${fromEmailAddress}`);

    // Explicitly structure the request with all parameters to ensure they're passed correctly
    const emailRequest: {
      to: string;
      subject: string;
      text: string;
      from: string;
      replyTo: string | string[];
      html?: string;
      scheduledAt?: string;
      cc?: string[];
      bcc?: string[];
    } = {
      to,
      subject,
      text,
      from: fromEmailAddress,
      replyTo: replyToEmailAddresses,
    };

    // Add optional parameters conditionally
    if (html) {
      emailRequest.html = html;
    }

    if (scheduledAt) {
      emailRequest.scheduledAt = scheduledAt;
    }

    if (cc) {
      emailRequest.cc = cc;
    }

    if (bcc) {
      emailRequest.bcc = bcc;
    }

    console.error(`Email request: ${JSON.stringify(emailRequest)}`);

    const response = await resend.emails.send(emailRequest);

    if (response.error) {
      throw new Error(
        `Email failed to send: ${JSON.stringify(response.error)}`,
      );
    }

    return {
      content: [
        {
          type: 'text',
          text: `Email sent successfully! ${JSON.stringify(response.data)}`,
        },
      ],
    };
  },
});

server.tool({
  name: 'list-audiences',
  description:
    'List the available audiences from Resend. This tool is useful for getting the audience ID to help the user find the audience they want to use for other tools. If you need an audience ID, you MUST use this tool to get all available audiences and then ask the user to select the audience they want to use.',
  inputs: [],
  cb: async (params: any, context?: { req: any; res: any }) => {
    const resend = new Resend(context?.req.apiKey);

    console.error('Debug - Listing audiences');

    const response = await resend.audiences.list();

    if (response.error) {
      throw new Error(
        `Failed to list audiences: ${JSON.stringify(response.error)}`,
      );
    }

    return {
      content: [
        {
          type: 'text',
          text: `Audiences found: ${JSON.stringify(response.data)}`,
        },
      ],
    };
  },
});

async function main() {
  await server.listen(Number(port));
  console.error(`Email sending service MCP Server running on http://localhost:${port}`);
}

main().catch((error) => {
  console.error('Fatal error in main():', error);
  process.exit(1);
});
